import { useRef, useActionState } from 'react';

type FormState = {
  success: boolean;
  message: string;
  errors?: {
    name?: string;
    email?: string;
    message?: string;
  };
};

async function submitContactForm(prevState: FormState, formData: FormData): Promise<FormState> {
  'use server';

  const name = formData.get('name') as string;
  const email = formData.get('email') as string;
  const message = formData.get('message') as string;

  const errors: FormState['errors'] = {};

  if (!name || name.trim() === '') {
    errors.name = 'Name is required';
  }

  if (!email || email.trim() === '') {
    errors.email = 'Email is required';
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.email = 'Please enter a valid email address';
  }

  if (!message || message.trim() === '') {
    errors.message = 'Message is required';
  }

  if (Object.keys(errors).length > 0) {
    return {
      success: false,
      message: 'Please fix the errors below',
      errors,
    };
  }

  // Simulate saving contact message
  console.log('Contact form submitted:', { name, email, message });

  return {
    success: true,
    message: 'Thank you! Your message has been sent successfully.',
  };
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContactForm, {
    success: false,
    message: '',
  });

  const formRef = useRef<HTMLFormElement>(null);

  if (state.success && formRef.current) {
    formRef.current.reset();
  }

  return (
    <div style={{ maxWidth: '500px', margin: '0 auto', padding: '20px' }}>
      <h2>Contact Us</h2>
      <form ref={formRef} action={formAction} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>
            Name
          </label>
          <input
            type="text"
            id="name"
            name="name"
            placeholder="Your name"
            style={{ width: '100%', padding: '8px', fontSize: '14px' }}
          />
          {state.errors?.name && (
            <p style={{ color: 'red', fontSize: '12px', marginTop: '3px' }}>{state.errors.name}</p>
          )}
        </div>

        <div>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>
            Email
          </label>
          <input
            type="email"
            id="email"
            name="email"
            placeholder="your@email.com"
            style={{ width: '100%', padding: '8px', fontSize: '14px' }}
          />
          {state.errors?.email && (
            <p style={{ color: 'red', fontSize: '12px', marginTop: '3px' }}>{state.errors.email}</p>
          )}
        </div>

        <div>
          <label htmlFor="message" style={{ display: 'block', marginBottom: '5px' }}>
            Message
          </label>
          <textarea
            id="message"
            name="message"
            rows={4}
            placeholder="Your message"
            style={{ width: '100%', padding: '8px', fontSize: '14px', resize: 'vertical' }}
          />
          {state.errors?.message && (
            <p style={{ color: 'red', fontSize: '12px', marginTop: '3px' }}>{state.errors.message}</p>
          )}
        </div>

        <button
          type="submit"
          disabled={isPending}
          style={{
            padding: '10px 20px',
            backgroundColor: isPending ? '#ccc' : '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: isPending ? 'not-allowed' : 'pointer',
            fontSize: '16px',
          }}
        >
          {isPending ? 'Sending...' : 'Send Message'}
        </button>

        {state.message && (
          <p
            style={{
              color: state.success ? 'green' : 'red',
              padding: '10px',
              borderRadius: '5px',
              backgroundColor: state.success ? '#e6f4ea' : '#fce8e8',
            }}
          >
            {state.message}
          </p>
        )}
      </form>
    </div>
  );
}

